// ParseProxyRpcIds converts a comma-separated string to a slice of ProxyRpcId enum values
// Returns an error if any value is invalid
func ParseProxyRpcIds(s string) ([]ProxyRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]ProxyRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseProxyRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

